package app;

import java.time.Instant;
import java.util.List;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.validation.annotation.Validated;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;

@Service
@Validated
public class OrderService {

    private final OrderRepository orderRepository;

    public OrderService(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }

    @Transactional
    public OrderConfirmation placeOrder(@Valid PlaceOrderRequest request) {
        Order order = Order.create(request.customerId(), request.items(), Instant.now());
        Order saved = orderRepository.save(order);
        return new OrderConfirmation(saved.id(), saved.customerId(), saved.createdAt());
    }
}

interface OrderRepository {
    Order save(Order order);
}

record Order(Long id, String customerId, List<OrderLine> lines, Instant createdAt) {

    static Order create(String customerId, List<OrderLine> lines, Instant createdAt) {
        return new Order(null, customerId, List.copyOf(lines), createdAt);
    }

    Order withId(long id) {
        return new Order(id, customerId, lines, createdAt);
    }
}

record OrderLine(@NotBlank String sku, @jakarta.validation.constraints.Positive int quantity) {}

record PlaceOrderRequest(@NotBlank String customerId, @NotEmpty List<OrderLine> items) {}

record OrderConfirmation(Long id, String customerId, Instant createdAt) {}

